mapper.select:
select t1.id, t1.plan_no, t1.batch_no, t1.product_date, t1.type, t1.product_id, t1.product_name, t1.product_merge_code, t1.product_specification, t1.process_id, t1.process_name, t1.process_version, t1.status, t1.instruct_status, t1.process_instance_id, t1.unit_id, t1.batch_quantity batchQuantityDecimal, t1.production_line_id, t1.create_time, t1.execute_paused paused, t1.is_start as start, t1.production_plan_item_id from bm_product_plan t1 where t1.is_deleted = 0
and t1.id in
#{planId}
and t1.plan_no like concat('%',#{planNo},'%')
and t1.batch_no like concat('%',#{batchNo},'%')
and t1.product_name like concat('%',#{productName},'%')
and t1.process_name like concat('%',#{processName},'%')
and t1.type = #{type}
and t1.status = #{status}
and t1.instruct_status in
#{insStatus}
and t1.is_start = #{isStart}
and t1.execute_paused = #{paused}
order by t1.create_time desc,t1.id desc

select t1.id, t1.batch_no from bm_product_plan t1 where t1.instruct_status = 'SEND'
and t1.process_id = #{processId}
and t1.batch_no like concat('%', #{batchNo},'%')
and t1.is_relation = #{relation}
order by t1.create_time asc

select t1.id, t1.plan_no, t1.batch_no, t1.product_date, t1.type, t1.product_id, t1.product_name, t1.product_merge_code, t1.product_specification, t1.execute_process_instance_id, t1.process_id, t1.process_name, t1.process_version, t1.execute_paused, t1.start_time, t1.production_line_id, t2.process_model_id, t2.id as processVersionId, count(t3.id) as exceptionCount from bm_product_plan t1 left join bm_process_version t2 on t1.process_id = t2.process_id and t1.process_version = t2.version left join bm_execute_exception t3 on t3.product_plan_id = t1.id where t1.is_deleted = 0 and t1.is_start = 'STARTING'
and t1.id in
#{planId}
and t1.batch_no like concat('%',#{batchNo},'%')
and t1.product_id = #{productId}
and t1.production_line_id in
#{lineId}
and t1.id in
#{item}
and t1.product_id in
#{pId}
and t1.start_time between concat(#{startTime}, ' 00:00:00') and concat(#{endTime}, ' 23:59:59')
and t1.product_name like concat('%',#{productName},'%')
group by t1.id
order by ${orderBy}
order by t1.start_time desc

select t1.id, t1.plan_no, t1.batch_no, t1.product_date, t1.type, t1.product_id, t1.product_name, t1.product_merge_code, t1.product_specification, t1.execute_process_instance_id, t1.process_id, t1.process_name, t1.process_version, t1.start_time, t1.end_time, t1.is_start as `start`, t1.instruct_status, t1.archive_status, t1.production_line_id, count(t2.id) as `exception_count` from bm_product_plan t1 left join bm_execute_exception t2 on t2.product_plan_id = t1.id where t1.is_deleted = 0 and t1.is_start in ('END','TERMINATION')
and t1.process_id in ( select resource_id from bm_resource_permission where dept_id in
#{item}
)
and t1.batch_no like concat('%',#{batchNo},'%')
and t1.process_name like concat('%',#{processName},'%')
and t1.start_time between concat(#{startTime}, ' 00:00:00') and concat(#{endTime}, ' 23:59:59')
and t1.product_id in
#{item}
group by t1.id order by t1.start_time desc

SELECT DISTINCT t3.id, t3.status FROM bm_process t1 JOIN bm_resource_permission t2 ON t1.id = t2.resource_id JOIN bm_product_plan AS t3 ON t1.id = t3.process_id WHERE t1.is_deleted = 0 AND t3.is_deleted = 0
AND t2.dept_id IN
#{item}

select t1.id, t1.plan_no, t1.batch_no, t1.product_date, t1.type, t1.product_id, t1.product_name, t1.product_merge_code, t1.product_specification, t1.execute_process_instance_id, t1.process_id, t1.process_name, t1.process_version, t1.execute_paused, t1.start_time, t2.process_model_id, t2.id as processVersionId, t1.production_line_id as productionLineId from bm_product_plan t1 left join bm_process_version t2 on t1.process_id = t2.process_id and t1.process_version = t2.version where t1.is_deleted = 0 and (t1.is_start = 'END' OR t1.is_start = 'TERMINATION')
and t1.id in
#{planId}
and t1.batch_no like concat('%',#{batchNo},'%')
and t1.product_id in
#{pId}
and t1.production_line_id in
#{lineId}
order by ${orderBy}
order by t1.start_time desc

SELECT bm_product_plan.* FROM bm_product_plan LEFT JOIN bm_product_instruction ON bm_product_plan.id = bm_product_instruction.product_plan_id WHERE bm_product_plan.is_deleted = 0 and bm_product_plan.id IN
#{pId}
GROUP BY bm_product_plan.id HAVING SUM(bm_product_instruction.status = 'RESOLVE') = 0;

select t1.id, t1.plan_no, t1.batch_no, t1.product_date, t1.type, t1.product_id, t1.product_name, t1.product_merge_code, t1.product_specification, t1.execute_process_instance_id, t1.process_id, t1.process_name, t1.process_version, t1.start_time, t1.end_time, t1.is_start as `start`, t1.archive_status from bm_product_plan t1 where t1.is_deleted = 0 and t1.is_start in ('END','STARTING','TERMINATION')
and t1.process_id in ( select resource_id from bm_resource_permission where dept_id in
#{item}
)
and t1.batch_no like concat('%',#{batchNo},'%')
and t1.process_name like concat('%',#{processName},'%')
and t1.product_id in
#{item}
group by t1.id order by t1.start_time desc

SELECT
FROM bm_product_plan WHERE is_deleted = 0 AND
process_id = #{item.processId} AND process_version = #{item.version}
ORDER BY start_time DESC LIMIT 0, #{n}

select
    t1.id
from bm_product_plan t1
left join bm_process_version t2 on t1.process_id = t2.process_id and t1.process_version = t2.version
left join bm_execute_exception t3 on t3.product_plan_id = t1.id
where t1.is_deleted = 0

    and t1.is_start =#{dto.isStart}


    and t1.batch_no like concat('%',#{dto.batchNo},'%')


    and t1.product_id = #{dto.productId}


    and t1.production_line_id =#{dto.lineId}


    and t1.id in

        #{item}



    and t1.product_id in

        #{pId}


group by t1.id
